      const errDescription = result.summary.replace(/\n/g, "; ");
      console.log(`INVALID: ${errDescription}`);
    } else {
      console.log("VALID");
      console.log(JSON.stringify(result));
    }
  } catch (e: any) {
    console.log(`INVALID: Unexpected error: ${e.message}`);
  }
  process.exit(0);
}

main();
